Nix attrsets are pure functional key-value structures with unique evaluation semantics:

```nix
# Basic attrset (JSON-like but with Nix semantics)
{ name = "purenix"; version = "1.0"; }

# Nested attrset (attribute paths)
{ services = { nginx = { enable = true; port = 8080; }; }; }
# Access via: config.services.nginx.enable

# Recursive attrset (self-reference with 'rec')
rec {
  a = 1;
  b = a + 1;  # 'a' accessible within same scope
  c = b * 2;
}

# Inheritance (extend existing attrset)
base = { x = 1; y = 2; };
extended = base // { z = 3; };  # → { x = 1; y = 2; z = 3; }

# Conditional attributes (idiomatic Nix)
options = {
  enable ? false,
  port ? 8080,
} // (if options.enable then { actualPort = options.port; } else {});
```

