# default.nix (Docker image builder)
{ pkgs, lib }:

let
  # Your application binary
  myApp = pkgs.callPackage ./my-app.nix {};

  # Distroless base image (no shell, minimal attack surface)
  distrolessBase = pkgs.dockerTools.mkImage {
    contents = [ ];  # Empty base
    config = {
      Env = [ "PATH=/bin" ];
      WorkingDir = "/";
    };
  };

  # Final image with just your binary
  myAppImage = pkgs.dockerTools.buildLayeredImage {
    name = "my-registry/my-app";
    tag = "1.0.0";

    # Minimal contents – only your binary + required libs
    contents = [
      myApp
      pkgs.glibc  # Required for dynamic linking
    ];

    # Configuration
    config = {
      Cmd = [ "${myApp}/bin/my-app" "--port=8080" ];
      ExposedPorts = { "8080/tcp" = { }; };
      Env = [ "PORT=8080" ];
    };

    # Maximize reproducibility
    created = "1970-01-01T00:00:01Z";  # Fixed timestamp
    maxLayers = 1;  # Single layer for minimal size
  };
in
  myAppImage
```

Build and load:
```bash
# Build image
nix-build -E 'with import <nixpkgs> {}; callPackage ./default.nix {}'

# Load into Docker daemon
docker load < result

docker run -p 8080:8080 my-registry/my-app:1.0.0
```

Alternative: Export directly to registry (Nix 2.4+)
