# flake.nix (cross-compilation setup)
{
  description = "Cross-compile ARM64 binaries from x86_64";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-25.11";
    flake-utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, flake-utils }:
    let
      # Host system (where build runs)
      hostSystem = "x86_64-linux";

      # Target system (what we're building FOR)
      targetSystem = "aarch64-linux";

      # Native pkgs (for host)
      pkgs = nixpkgs.legacyPackages.${hostSystem};

      # Cross-compilation toolchain
      pkgsCross = nixpkgs.legacyPackages.${hostSystem}.pkgsCross.${targetSystem};
    in {
      # Native build (x86_64)
      packages.x86_64-linux.default = pkgs.callPackage ./my-app.nix {};

      # Cross-compiled build (ARM64)
      packages.aarch64-linux.default = pkgsCross.callPackage ./my-app.nix {};

      # Dev shell with cross toolchain
      devShells.default = pkgs.mkShell {
        packages = [
          pkgsCross.gcc
          pkgsCross.binutils
          pkgs.qemu
        ];
        shellHook = ''
          export CC=${pkgsCross.gcc}/bin/aarch64-unknown-linux-gnu-gcc
          echo "✓ Cross toolchain for ${targetSystem} ready"
          echo "✓ Test with: qemu-aarch64 -L ${pkgsCross.stdenv.cc.libc} ./my-app"
        '';
      };

      # Convenience: build all targets
      packages.default = flake-utils.lib.genAttrs [ "x86_64-linux" "aarch64-linux" ]
        (system: self.packages.${system}.default);
    };
}
```

Build workflow:
```bash
# Build ARM64 binary on x86_64 host
nix build .#packages.aarch64-linux.default

# Verify architecture
file ./result/bin/my-app
# → ELF 64-bit LSB executable, ARM aarch64

# Test with QEMU
qemu-aarch64 -L $(nix-build -E 'with import <nixpkgs> {}; pkgs.pkgsCross.aarch64-multiplatform.stdenv.cc.libc') ./result/bin/my-app
```

⚠️ NOT all packages support cross-compilation – check with `nix repl` → `:l <nixpkgs/pkgsCross>`
⚠️ C/C++ projects typically cross-compile well; Rust/Go require target-specific toolchains
⚠️ NixOS 25.11 supports 12 cross targets including aarch64, riscv64, wasm32 [[16]]
⚠️ Cross builds often slower – no binary cache hits for cross-compiled packages
⚠️ For Docker multi-arch: combine with `pkgs.dockerTools.buildImageArchitectures`
